import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useOSStore } from '../store/useOSStore';
import { APPS } from '../apps/registry';
import {
  Smartphone,
  Tablet,
  ChevronRight,
  ChevronLeft,
  Scan,
  Radio,
  MessageSquare,
  Cpu,
  Music,
  Camera,
  UserCheck,
  Gamepad2,
  Sparkles,
  Shield,
  Play,
  Pause,
  AlertTriangle,
  Zap,
  Minimize2
} from 'lucide-react';

export default function PhoneWidget() {
  const [isDocked, setIsDocked] = useState(false);
  const [deviceMode, setDeviceMode] = useState('phone'); // 'phone' | 'tablet'
  const [screenApp, setScreenApp] = useState('home'); // 'home' | 'scanner' | 'comms' | 'supercalc' | 'music' | 'camera' | 'status'
  const [isPlaying, setIsPlaying] = useState(false);
  const [virtualizing, setVirtualizing] = useState(false);
  const [scannerLog, setScannerLog] = useState('');
  const [chatMessages, setChatMessages] = useState([
    { id: 1, sender: 'Jeremie Belpois', text: 'Super-calculator detected tower activation in Ice Sector!', time: '09:40' },
    { id: 2, sender: 'Aelita', text: 'Transferring Code Lyoko keys to Cyacademy mesh network.', time: '09:41' },
    { id: 3, sender: 'Ulrich', text: 'Overwing ready. Awaiting virtualization command.', time: '09:42' },
    { id: 4, sender: 'Odd', text: 'Laser arrows locked and loaded!', time: '09:43' },
  ]);
  const [chatInput, setChatInput] = useState('');

  const toggleApp = useOSStore((s) => s.toggleApp);
  const player = useOSStore((s) => s.gameplay.player);
  const addCredits = useOSStore((s) => s.addCredits);
  const addXP = useOSStore((s) => s.addXP);

  const handleLaunchDesktopApp = (appId) => {
    const targetApp = APPS.find((a) => a.id === appId);
    if (targetApp) {
      toggleApp(targetApp);
    }
  };

  const handleVirtualize = () => {
    setVirtualizing(true);
    setScannerLog('⚡ CODE LYOKO VIRTUALIZATION SCANNER INITIALIZED...');
    setTimeout(() => {
      setVirtualizing(false);
      addCredits(150);
      addXP(75);
      setScannerLog('✅ VIRTUALIZATION COMPLETE! TRANSFERRED TO LYOKO SECTOR 5 (+150 ₡, +75 XP).');
    }, 1200);
  };

  const handleSendChat = (e) => {
    if (e.key !== 'Enter' || !chatInput.trim()) return;
    setChatMessages((prev) => [
      ...prev,
      { id: Date.now(), sender: 'PLAYERNAME (You)', text: chatInput.trim(), time: 'Just now' },
    ]);
    setChatInput('');
  };

  return (
    <div
      className={`fixed right-0 top-1/2 -translate-y-1/2 z-40 transition-transform duration-500 ease-in-out flex items-center ${
        isDocked ? 'translate-x-[calc(100%-36px)]' : 'translate-x-0'
      }`}
    >
      {/* ------------------------------------------------------------------ */}
      {/* EDGE DOCKING TOGGLE TAB (WHEN DOCKED)                               */}
      {/* ------------------------------------------------------------------ */}
      <button
        onClick={() => setIsDocked((prev) => !prev)}
        className="flex h-28 w-9 flex-col items-center justify-center rounded-l-2xl border-l-2 border-y-2 border-cyan-400/80 bg-slate-900/90 text-cyan-300 shadow-[0_0_20px_rgba(77,243,255,0.4)] hover:bg-slate-800 transition cursor-pointer backdrop-blur-md z-50 shrink-0"
        title={isDocked ? 'Open Super-Communicator' : 'Dock Communicator to Right Edge'}
      >
        {isDocked ? (
          <>
            <ChevronLeft size={18} className="animate-bounce" />
            <Smartphone size={16} className="my-1" />
            <span className="text-[9px] font-mono font-bold tracking-widest uppercase rotate-90 my-2">COMM</span>
          </>
        ) : (
          <>
            <ChevronRight size={18} />
            <Minimize2 size={16} className="my-1" />
            <span className="text-[9px] font-mono font-bold tracking-widest uppercase rotate-90 my-2">HIDE</span>
          </>
        )}
      </button>

      {/* ------------------------------------------------------------------ */}
      {/* CODE LYOKO SUPER-COMMUNICATOR / CYBER-TABLET WIDGET BODY           */}
      {/* ------------------------------------------------------------------ */}
      <motion.div
        layout
        transition={{ type: 'spring', stiffness: 300, damping: 30 }}
        className={`relative select-none overflow-hidden transition-all duration-300 ${
          deviceMode === 'tablet'
            ? 'w-[560px] h-[480px] rounded-[36px] border-[10px] border-slate-900 bg-slate-950 shadow-[0_25px_70px_rgba(140,100,250,0.4)]'
            : 'w-[240px] h-[460px] rounded-[42px] border-[10px] border-[#1C1C1E] bg-[#1C1C1E] shadow-[0_25px_60px_rgba(0,0,0,0.5)]'
        }`}
      >
        {/* Top Dynamic Island / Bezel Header Controls */}
        <div className="absolute top-0 left-0 right-0 h-7 bg-[#1C1C1E] z-30 px-4 flex items-center justify-between text-white/80">
          <div className="flex items-center gap-1.5 text-[9px] font-mono font-bold text-cyan-300">
            <Radio size={12} className="animate-pulse" />
            <span>{deviceMode === 'tablet' ? 'SUPER-CALCULATOR TABLET' : 'LYOKO COMM'}</span>
          </div>

          {/* Morph Device Mode Toggle (Phone ↔ Tablet) */}
          <button
            onClick={() => setDeviceMode((prev) => (prev === 'phone' ? 'tablet' : 'phone'))}
            className="flex items-center gap-1 rounded-full bg-white/10 hover:bg-white/20 px-2 py-0.5 text-[9px] font-bold text-amber-300 transition"
            title={deviceMode === 'phone' ? 'Expand to Cyber-Tablet' : 'Switch to Phone Mode'}
          >
            {deviceMode === 'phone' ? (
              <>
                <Tablet size={12} /> Expand ↔
              </>
            ) : (
              <>
                <Smartphone size={12} /> Phone Mode 📱
              </>
            )}
          </button>
        </div>

        {/* Screen Frame with Starry Cyber Wallpaper */}
        <div
          className="relative h-full w-full overflow-hidden bg-cover bg-center flex flex-col justify-between p-3 pt-8 text-white"
          style={{
            backgroundImage: `url('https://images.unsplash.com/photo-1506703719100-a0f3a48c0f86?q=80&w=600&auto=format&fit=crop')`,
          }}
        >
          {/* Dark Overlay Gradient */}
          <div className="absolute inset-0 bg-gradient-to-b from-black/60 via-black/30 to-black/80 pointer-events-none" />

          {/* Virtual Scanner Beam Overlay */}
          {virtualizing && (
            <div className="absolute inset-0 z-50 pointer-events-none flex flex-col justify-between overflow-hidden">
              <div className="w-full h-2 bg-amber-400 shadow-[0_0_20px_#FFD86B] animate-bounce" />
              <div className="bg-amber-500/15 inset-0 absolute flex items-center justify-center font-mono font-bold text-amber-300 text-xs tracking-widest uppercase animate-pulse">
                <Scan size={28} className="mr-2 animate-spin text-amber-400" /> Virtualizing to Lyoko...
              </div>
            </div>
          )}

          {/* Top Status Bar */}
          <div className="relative z-10 flex justify-between items-center text-[10px] font-bold px-2 text-white/90">
            <span>09:41</span>
            <div className="flex gap-1.5 items-center font-mono text-[9px] text-cyan-300">
              <span>📶 LYOKO_NET</span>
              <span>🔋 100%</span>
            </div>
          </div>

          {/* ------------------------------------------------------------------ */}
          {/* SCREEN CONTENT AREA (PHONE VS TABLET MULTI-PANE)                    */}
          {/* ------------------------------------------------------------------ */}
          <div className="relative z-10 my-auto flex-1 flex flex-col justify-center w-full py-2 overflow-hidden">
            {/* HOME SCREEN APP GRID */}
            {screenApp === 'home' && (
              <div className="w-full space-y-3">
                {/* Player Identity Pill */}
                <button
                  onClick={() => setScreenApp('status')}
                  className="w-full rounded-2xl bg-white/15 backdrop-blur-md border border-white/25 p-2 flex items-center justify-between hover:bg-white/25 transition shadow"
                >
                  <div className="flex items-center gap-2">
                    <div className="w-7 h-7 rounded-full bg-purple-400/30 border border-purple-200 flex items-center justify-center font-bold text-xs">
                      P
                    </div>
                    <div className="text-left">
                      <div className="text-[10px] font-bold text-white leading-none">PLAYERNAME</div>
                      <div className="text-[9px] text-cyan-300">Level {player.level} • ₡{player.credits}</div>
                    </div>
                  </div>
                  <Shield size={14} className="text-emerald-400" />
                </button>

                {/* On-Screen App Tile Buttons */}
                <div className={`grid gap-2.5 ${deviceMode === 'tablet' ? 'grid-cols-6' : 'grid-cols-3'}`}>
                  {/* Lyoko Virtual Scanner */}
                  <button
                    onClick={() => setScreenApp('scanner')}
                    className="flex flex-col items-center group"
                  >
                    <div className="h-11 w-11 rounded-2xl bg-gradient-to-br from-amber-400/80 to-orange-600/80 backdrop-blur-md border border-white/30 shadow flex items-center justify-center text-white group-hover:scale-105 transition">
                      <Scan size={20} />
                    </div>
                    <span className="text-[9px] font-medium text-white/90 mt-1">Lyoko Scanner</span>
                  </button>

                  {/* Lyoko Warrior Comms */}
                  <button
                    onClick={() => setScreenApp('comms')}
                    className="flex flex-col items-center group"
                  >
                    <div className="h-11 w-11 rounded-2xl bg-gradient-to-br from-pink-400/80 to-purple-600/80 backdrop-blur-md border border-white/30 shadow flex items-center justify-center text-white group-hover:scale-105 transition">
                      <MessageSquare size={20} />
                    </div>
                    <span className="text-[9px] font-medium text-white/90 mt-1">Warrior Comms</span>
                  </button>

                  {/* Super-Calculator Diagnostics */}
                  <button
                    onClick={() => setScreenApp('supercalc')}
                    className="flex flex-col items-center group"
                  >
                    <div className="h-11 w-11 rounded-2xl bg-gradient-to-br from-cyan-400/80 to-blue-600/80 backdrop-blur-md border border-white/30 shadow flex items-center justify-center text-white group-hover:scale-105 transition">
                      <Cpu size={20} />
                    </div>
                    <span className="text-[9px] font-medium text-white/90 mt-1">Super-Calc</span>
                  </button>

                  {/* Aura Passport App (Launches Desktop App) */}
                  <button
                    onClick={() => handleLaunchDesktopApp('passport')}
                    className="flex flex-col items-center group"
                  >
                    <div className="h-11 w-11 rounded-2xl bg-gradient-to-br from-violet-400/80 to-purple-700/80 backdrop-blur-md border border-white/30 shadow flex items-center justify-center text-white group-hover:scale-105 transition">
                      <UserCheck size={20} />
                    </div>
                    <span className="text-[9px] font-medium text-white/90 mt-1">Passport OS</span>
                  </button>

                  {/* Game Hub (Launches Desktop App) */}
                  <button
                    onClick={() => handleLaunchDesktopApp('gamehub')}
                    className="flex flex-col items-center group"
                  >
                    <div className="h-11 w-11 rounded-2xl bg-gradient-to-br from-indigo-400/80 to-blue-700/80 backdrop-blur-md border border-white/30 shadow flex items-center justify-center text-white group-hover:scale-105 transition">
                      <Gamepad2 size={20} />
                    </div>
                    <span className="text-[9px] font-medium text-white/90 mt-1">Games OS</span>
                  </button>

                  {/* SpellForge (Launches Desktop App) */}
                  <button
                    onClick={() => handleLaunchDesktopApp('spellforge')}
                    className="flex flex-col items-center group"
                  >
                    <div className="h-11 w-11 rounded-2xl bg-gradient-to-br from-fuchsia-400/80 to-pink-700/80 backdrop-blur-md border border-white/30 shadow flex items-center justify-center text-white group-hover:scale-105 transition">
                      <Sparkles size={20} />
                    </div>
                    <span className="text-[9px] font-medium text-white/90 mt-1">SpellForge OS</span>
                  </button>

                  {/* Music Player */}
                  <button
                    onClick={() => setScreenApp('music')}
                    className="flex flex-col items-center group"
                  >
                    <div className="h-11 w-11 rounded-2xl bg-gradient-to-br from-emerald-400/80 to-teal-600/80 backdrop-blur-md border border-white/30 shadow flex items-center justify-center text-white group-hover:scale-105 transition">
                      <Music size={20} />
                    </div>
                    <span className="text-[9px] font-medium text-white/90 mt-1">Music</span>
                  </button>

                  {/* Camera */}
                  <button
                    onClick={() => setScreenApp('camera')}
                    className="flex flex-col items-center group"
                  >
                    <div className="h-11 w-11 rounded-2xl bg-gradient-to-br from-slate-400/80 to-slate-700/80 backdrop-blur-md border border-white/30 shadow flex items-center justify-center text-white group-hover:scale-105 transition">
                      <Camera size={20} />
                    </div>
                    <span className="text-[9px] font-medium text-white/90 mt-1">Camera</span>
                  </button>
                </div>
              </div>
            )}

            {/* LYOKO VIRTUAL SCANNER APP */}
            {screenApp === 'scanner' && (
              <div className="w-full h-full flex flex-col justify-between bg-black/80 backdrop-blur-md rounded-2xl p-3 border border-amber-400/30 text-xs">
                <div className="flex items-center justify-between border-b border-amber-400/30 pb-2">
                  <button onClick={() => setScreenApp('home')} className="text-white/70 hover:text-white flex items-center gap-1">
                    <ChevronLeft size={14} /> Back
                  </button>
                  <span className="font-bold font-mono text-amber-300 text-[11px]">VIRTUAL SCANNER</span>
                  <Scan size={14} className="text-amber-400" />
                </div>

                <div className="space-y-2 my-2 font-mono text-[10px]">
                  <div className="flex justify-between items-center rounded-lg bg-white/5 p-1.5 border border-white/10">
                    <span className="text-cyan-300">Ice Sector (Tower 4)</span>
                    <span className="text-pink-400 font-bold flex items-center gap-1">
                      <AlertTriangle size={12} /> TOWER ACTIVATED
                    </span>
                  </div>

                  <div className="flex justify-between items-center rounded-lg bg-white/5 p-1.5 border border-white/10">
                    <span className="text-white/70">Desert Sector (Tower 12)</span>
                    <span className="text-emerald-400">INACTIVE</span>
                  </div>

                  <div className="flex justify-between items-center rounded-lg bg-white/5 p-1.5 border border-white/10">
                    <span className="text-white/70">Sector 5 (Celestial Dome)</span>
                    <span className="text-purple-400">AELITA SYNCED</span>
                  </div>

                  {scannerLog && (
                    <div className="rounded-lg bg-slate-900 border border-cyan-400/40 p-2 text-cyan-300 font-mono text-[9px] animate-fade-in">
                      {scannerLog}
                    </div>
                  )}
                </div>

                <button
                  onClick={handleVirtualize}
                  disabled={virtualizing}
                  className="w-full rounded-xl border border-amber-400 bg-amber-500/20 py-2 font-bold font-mono text-amber-300 hover:bg-amber-500/40 transition shadow text-xs flex items-center justify-center gap-2"
                >
                  <Zap size={14} className="text-amber-400 animate-pulse" /> [ VIRTUALIZE TO LYOKO ]
                </button>
              </div>
            )}

            {/* LYOKO WARRIOR MESH COMMS APP */}
            {screenApp === 'comms' && (
              <div className="w-full h-full flex flex-col justify-between bg-black/85 backdrop-blur-md rounded-2xl p-3 border border-pink-400/30 text-xs">
                <div className="flex items-center justify-between border-b border-pink-400/30 pb-2">
                  <button onClick={() => setScreenApp('home')} className="text-white/70 hover:text-white flex items-center gap-1">
                    <ChevronLeft size={14} /> Back
                  </button>
                  <span className="font-bold font-mono text-pink-300 text-[11px]">LYOKO WARRIORS MESH</span>
                  <MessageSquare size={14} className="text-pink-400" />
                </div>

                <div className="flex-1 overflow-auto space-y-2 my-2 pr-1">
                  {chatMessages.map((msg) => (
                    <div key={msg.id} className="rounded-lg bg-white/5 p-2 border border-white/10 space-y-0.5">
                      <div className="flex justify-between items-center text-[9px]">
                        <span className="font-bold text-cyan-300">{msg.sender}</span>
                        <span className="text-white/40">{msg.time}</span>
                      </div>
                      <div className="text-white/90 text-[10px]">{msg.text}</div>
                    </div>
                  ))}
                </div>

                <input
                  type="text"
                  value={chatInput}
                  onChange={(e) => setChatInput(e.target.value)}
                  onKeyDown={handleSendChat}
                  placeholder="Send message to Lyoko team..."
                  className="w-full rounded-xl border border-pink-400/40 bg-black/60 px-3 py-1.5 text-xs text-white outline-none focus:border-pink-400 font-mono"
                />
              </div>
            )}

            {/* SUPER-CALCULATOR DIAGNOSTICS APP */}
            {screenApp === 'supercalc' && (
              <div className="w-full h-full flex flex-col justify-between bg-black/80 backdrop-blur-md rounded-2xl p-3 border border-cyan-400/30 text-xs font-mono">
                <div className="flex items-center justify-between border-b border-cyan-400/30 pb-2">
                  <button onClick={() => setScreenApp('home')} className="text-white/70 hover:text-white flex items-center gap-1">
                    <ChevronLeft size={14} /> Back
                  </button>
                  <span className="font-bold text-cyan-300 text-[11px]">SUPER-CALCULATOR DIAGNOSTICS</span>
                  <Cpu size={14} className="text-cyan-400" />
                </div>

                <div className="space-y-2 my-2 text-[10px]">
                  <div className="flex justify-between border-b border-white/10 pb-1">
                    <span className="text-white/60">Subspace Freq:</span>
                    <span className="font-bold text-cyan-300">4.85 GHz</span>
                  </div>
                  <div className="flex justify-between border-b border-white/10 pb-1">
                    <span className="text-white/60">Quantum Core Load:</span>
                    <span className="font-bold text-emerald-400">34.2%</span>
                  </div>
                  <div className="flex justify-between border-b border-white/10 pb-1">
                    <span className="text-white/60">Reality Stability:</span>
                    <span className="font-bold text-purple-400">98.2%</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-white/60">Aethercore Buffer:</span>
                    <span className="font-bold text-amber-300">STABLE</span>
                  </div>
                </div>

                <button
                  onClick={() => alert('⚡ Super-calculator diagnostics refreshed!')}
                  className="w-full rounded-xl border border-cyan-400 bg-cyan-500/20 py-1.5 font-bold text-cyan-300 hover:bg-cyan-500/40 transition text-xs"
                >
                  [ REFRESH DIAGNOSTICS ]
                </button>
              </div>
            )}

            {/* MUSIC PLAYER */}
            {screenApp === 'music' && (
              <div className="w-full space-y-3 bg-black/75 backdrop-blur-md rounded-2xl p-3 border border-white/20">
                <div className="flex items-center justify-between">
                  <button onClick={() => setScreenApp('home')} className="text-white/70 hover:text-white">
                    <ChevronLeft size={16} />
                  </button>
                  <span className="text-[10px] font-bold text-cyan-300">Aether Synth Radio</span>
                  <div className="w-4" />
                </div>

                <div className="w-20 h-20 mx-auto rounded-xl bg-purple-900/60 border border-purple-400/40 flex items-center justify-center text-purple-300">
                  <Music size={32} className={isPlaying ? 'animate-bounce' : ''} />
                </div>

                <div className="text-center space-y-0.5">
                  <div className="text-[11px] font-bold text-white">Code Lyoko Theme (Synth Rework)</div>
                  <div className="text-[9px] text-white/60">Jeremie & Aelita Lo-Fi</div>
                </div>

                <button
                  onClick={() => setIsPlaying((prev) => !prev)}
                  className="w-10 h-10 mx-auto rounded-full bg-cyan-400 text-slate-950 flex items-center justify-center font-bold hover:scale-105 transition shadow"
                >
                  {isPlaying ? <Pause size={18} /> : <Play size={18} className="ml-0.5" />}
                </button>
              </div>
            )}

            {/* CAMERA VIEWFINDER */}
            {screenApp === 'camera' && (
              <div className="w-full space-y-2 bg-black/80 backdrop-blur-md rounded-2xl p-3 border border-white/20 text-center">
                <div className="flex items-center justify-between">
                  <button onClick={() => setScreenApp('home')} className="text-white/70 hover:text-white">
                    <ChevronLeft size={16} />
                  </button>
                  <span className="text-[10px] font-bold text-pink-400">Cyber Viewfinder</span>
                  <div className="w-4" />
                </div>

                <div className="relative w-full h-28 rounded-xl border border-dashed border-cyan-400/60 bg-black/40 overflow-hidden flex items-center justify-center">
                  <div className="absolute inset-2 border border-cyan-400/30 rounded-lg pointer-events-none" />
                  <span className="text-[10px] text-cyan-300 font-mono">AURA LENS: ACTIVE</span>
                </div>

                <button
                  onClick={() => alert('📷 Snapshot captured to Files archive!')}
                  className="w-8 h-8 mx-auto rounded-full border-2 border-white bg-white/30 hover:bg-white/50 transition shadow"
                />
              </div>
            )}

            {/* STATUS VIEW */}
            {screenApp === 'status' && (
              <div className="w-full space-y-2 bg-black/75 backdrop-blur-md rounded-2xl p-3 border border-white/20 text-xs">
                <div className="flex items-center justify-between border-b border-white/10 pb-1">
                  <button onClick={() => setScreenApp('home')} className="text-white/70 hover:text-white">
                    <ChevronLeft size={16} />
                  </button>
                  <span className="text-[10px] font-bold text-amber-300">Identity Status</span>
                  <div className="w-4" />
                </div>

                <div className="space-y-1.5 text-[10px]">
                  <div className="flex justify-between">
                    <span className="text-white/60">Level:</span>
                    <span className="font-bold text-emerald-400">Level {player.level}</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-white/60">XP Progress:</span>
                    <span className="font-bold text-cyan-300">{player.xp} XP</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-white/60">Credits:</span>
                    <span className="font-bold text-emerald-400">₡{player.credits}</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-white/60">Aura Health:</span>
                    <span className="font-bold text-purple-400">{player.auraHealth}%</span>
                  </div>
                </div>
              </div>
            )}
          </div>

          {/* Home Bar Indicator */}
          <div className="relative z-10 flex justify-center pb-1">
            <button
              onClick={() => setScreenApp('home')}
              className="h-1.5 w-20 bg-white/70 rounded-full hover:bg-white transition cursor-pointer"
              title="Return to Home Screen"
            />
          </div>
        </div>
      </motion.div>
    </div>
  );
}
